Theorem snprintf_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo prec d dst : Z) (obuf : list byte) (G : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 6000 <= bv_unsigned sp)%Z -> (bv_unsigned sp < 2 ^ 63)%Z -> (0xf8ac8 <= lo)%Z -> (bv_unsigned ra mod 2 = 0)%Z ->
  ro_cells rsegs m 0xc5ab8 [C8 (Z_to_bv 64 0xf8ac0)] -> ro_cells rsegs m 0xf8ac0 [C8 G] ->
  u8arr rsegs m dst obuf -> length obuf = 100%nat ->
  (prec = 15 \/ prec = 17)%Z -> (0 <= d < 2 ^ 64)%Z -> (d mod 2 ^ 63 <> 0)%Z ->
  (bv_unsigned sp <= dst)%Z -> (dst + 100 < 2 ^ 63)%Z ->
  a0 = Z_to_bv 64 dst -> a1 = Z_to_bv 64 100 -> a2 = Z_to_bv 64 0x12c0b -> a3 = Z_to_bv 64 prec -> a4 = Z_to_bv 64 d ->
  evt rsegs (fun ms' => exists (bs : list byte) t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' F' fc' m',
      (WDL.gnum (zs bs) = true \/ WDL.gspecial (zs bs)) /\ (1 <= Z.of_nat (length bs) <= 26)%Z /\
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (Z.of_nat (length bs))) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F'
               (ret_pc ra) fc' None m' (seg_rom rsegs)
      /\ fkeep F F'
      /\ munch [(lo, bv_unsigned sp); (dst, dst + 100)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ u8arr rsegs m' dst (upd_bytes obuf 0 (bs ++ [Z_to_bv 8 0])))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0xaedd8) fc None m (seg_rom rsegs)).
