Definition dotD (dot : bool) (d2 : list Z) : list Z := if dot then 46 :: d2 else [].
Lemma gdigits_of pre ds dot d2 ex sg de gr :
  WdGnum.alldig ds -> WdGnum.alldig d2 -> (dot = true -> (1 <= length d2)%nat /\ gr = 0) -> okE ex sg de -> (1 <= length pre)%nat ->
