Ltac lenlia := cbn [dotD length app] in *; rewrite ?length_app in *; cbn [length] in *; rewrite ?length_app in *; cbn [length] in *; rewrite ?length_app in *; cbn [length] in *; lia.
Ltac gside ADX Hdot := first [ assumption | (destruct (alldig_cons_inv _ _ ADX); assumption) | apply Forall_nil | (intros F; discriminate F) | (intros Hd; split; [exact (Hdot Hd) | reflexivity]) | lenlia ].
(* [comment removed for export] *)
Lemma gnum0_of SG c d1' dot d2 ex sg de :
  WdGnum.alldig (c :: d1') -> WdGnum.alldig d2 -> (dot = true -> (1 <= length d2)%nat) -> okE ex sg de ->
  Z.of_nat (length SG + S (length d1') + length (dotD dot d2) + length (tailE ex sg de)) <= 26 ->
  gnum0 (zb (SG ++ (c :: d1') ++ dotD dot d2 ++ tailE ex sg de ++ [0])) (Z.of_nat (length SG)) c.
Proof.
