Lemma grest_of SG d1 dot d2 ex sg de :
  WdGnum.alldig d1 -> (1 <= length d1)%nat -> WdGnum.alldig d2 -> (dot = true -> (1 <= length d2)%nat) -> okE ex sg de ->
